//! 表达式求值集成测试
//!
//! 仅通过公开 API 验证解析, 求值与错误的端到端行为.

use std::str::FromStr;

use expression::{
    Error, EvaluationContext, EvaluationError, Expression, Number, ParseError, ParseErrorKind,
    Value, ValueKind, evaluate, evaluate_constantly,
};

/// 测试上下文: 提供变量 hp=70, name="主角", flag=true 与函数 random
struct Context;

impl EvaluationContext for Context {
    fn get_variable(&self, name: &str) -> Option<Value> {
        match name {
            "hp" => Some(Value::from(70)),
            "name" => Some(Value::from("主角")),
            "flag" => Some(Value::from(true)),
            _ => None,
        }
    }

    fn call_function(&self, name: &str, arguments: &[Value]) -> Result<Value, EvaluationError> {
        match name {
            "random" => {
                if arguments.len() != 3 {
                    return Err(EvaluationError::ArgumentCount {
                        name: name.into(),
                        expected: 3,
                        got: arguments.len(),
                    });
                }
                Ok(Value::from(7))
            }
            _ => Err(EvaluationError::UnknownFunction(name.into())),
        }
    }
}

// -------- 求值 --------

#[test]
fn evaluate_arithmetic() {
    assert_eq!(evaluate("hp - 30", &Context).unwrap(), Value::from(40));
    assert_eq!(evaluate("1 + 2 * 3", &Context).unwrap(), Value::from(7));
    assert_eq!(
        evaluate("10 / 4", &Context).unwrap(),
        Value::Number(Number::Float(2.5))
    );
}

