#[test]
fn error_enum_conversion() {
    // 解析错误与求值错误均可自动转换为统一错误类型
    let parse_error = Error::from(Expression::from_str("").unwrap_err());
    assert!(matches!(parse_error, Error::Parse(_)));

    let evaluation_error = evaluate("1 / 0", &Context).unwrap_err();
    assert!(matches!(evaluation_error, Error::Evaluation(_)));
}

#[test]
fn evaluation_error_variants() {
    assert!(matches!(
        evaluate("foo(1)", &Context).unwrap_err(),
        Error::Evaluation(EvaluationError::UnknownFunction(name)) if name == "foo"
    ));
    assert!(matches!(
        evaluate("random(1)", &Context).unwrap_err(),
        Error::Evaluation(EvaluationError::ArgumentCount { .. })
    ));
    assert!(matches!(
        evaluate("1 / 0", &Context).unwrap_err(),
        Error::Evaluation(EvaluationError::DivisionByZero)
    ));
    assert!(matches!(
        evaluate("\"x\" - 1", &Context).unwrap_err(),
        Error::Evaluation(EvaluationError::TypeMismatch { op: "-", .. })
    ));
}

