#[test]
fn number_representation_preserved() {
    // 整数字面量与整数结果保持整数表示, 浮点保持浮点
    assert_eq!(
        evaluate("3", &Context).unwrap(),
        Value::Number(Number::Integer(3))
    );
    assert_eq!(
        evaluate("3.0", &Context).unwrap(),
        Value::Number(Number::Float(3.0))
    );
    assert_eq!(
        evaluate("1 + 2", &Context).unwrap(),
        Value::Number(Number::Integer(3))
    );
    assert_eq!(
        evaluate("1.5 + 1", &Context).unwrap(),
        Value::Number(Number::Float(2.5))
    );
    // 比较运算符按数值比较, 不区分表示
    assert_eq!(evaluate("3.0 == 3", &Context).unwrap(), Value::from(true));
}

