#[test]
fn expression_partial_eq() {
    assert_eq!(
        Expression::from_str("1 + 2").unwrap(),
        Expression::from_str("1+2").unwrap()
    );
    assert_ne!(
        Expression::from_str("1 + 2").unwrap(),
        Expression::from_str("1 + 3").unwrap()
    );
}

#[test]
fn expression_default() {
    // 默认表达式为字面量 0
    let expression = Expression::default();
    assert_eq!(expression.evaluate(&Context).unwrap(), Value::from(0));
    assert_eq!(expression.simplify().to_string(), "0");
}

// -------- 化简与格式化 --------

#[test]
fn simplify_expression() {
    let simplify = |source: &str| Expression::from_str(source).unwrap().simplify().to_string();
    assert_eq!(simplify("2 + 3 * 4"), "14");
    assert_eq!(simplify("1 > 0 ? \"高\" : \"低\""), "\"高\"");
    assert_eq!(simplify("false && a"), "false");
    // 非恒定表达式保持原样, 仅格式化 (紧凑, 不加空格)
    assert_eq!(simplify("hp > 0 ? 1 : 2"), "hp>0?1:2");
    assert_eq!(simplify("a && (b || c)"), "a&&(b||c)");
    assert_eq!(simplify("a - (b - c)"), "a-(b-c)");
}
